Import-Module ExchangeOnlineManagement
$upn = Read-Host 'Your authorized Exchange Online sign-in'
Connect-ExchangeOnline -UserPrincipalName $upn -ShowBanner:$false
try {
    $out = Join-Path ([IO.Path]::GetTempPath()) ("mailbox-inventory-{0}.csv" -f [guid]::NewGuid())
    ./Reference/Get-MailboxInventory.ps1 -Live -OutputCsv $out
    Import-Csv -LiteralPath $out | Group-Object RecipientTypeDetails | Select-Object Name, Count
    $out
} finally {
    Disconnect-ExchangeOnline -Confirm:$false
}

